before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::num::ParseIntError;
fn minutes(text: &str) -> Result<u32, ParseIntError> {
    let value = text.parse::<u32>()?;
    Ok(value)
}
fn main() {
    match minutes("12") {
        Ok(value) => println!("{value}"),
        Err(_) => println!("invalid"),
    }
}
```

